import test from 'node:test';
import assert from 'node:assert/strict';
import {RecursivePrimitiveKernel} from '../source/recursive-primitive-kernel.mjs';
import {ZhouyiExecutionAdapter} from '../source/zhouyi-execution-adapter.mjs';
function setup(){const kernel=new RecursivePrimitiveKernel();kernel.form({name:'adder',inputs:['x','y'],steps:[{id:'sum',op:'add',args:['x','y']}],output:'sum'});return {kernel,adapter:new ZhouyiExecutionAdapter(kernel)};}
test('bind does not confuse canonical lines with hash bucket',()=>{const {kernel,adapter}=setup();const b=adapter.bind('adder',63);assert.equal(b.six,63);assert.equal(b.hashBucket,kernel.get('adder').address.hexagram6);assert.deepEqual(adapter.state('adder').lines,[1,1,1,1,1,1]);});
test('line transition preserves identity and journals',()=>{const {adapter}=setup();adapter.bind('adder',0);adapter.transition('adder','line',1);adapter.transition('adder','complement');assert.equal(adapter.state('adder').six,62);assert.deepEqual(adapter.history().map(e=>e.kind),['bind','transition','transition']);});
test('execution uses existing VM and captures same state',async()=>{const {kernel,adapter}=setup();adapter.bind('adder',9);const {result,context}=await adapter.execute('adder',{x:2,y:5});assert.equal(result.value,7);assert.equal(context.six,9);assert.equal(adapter.history().at(-1).output,7);assert.equal(kernel.history().at(-1).event,'execute');});
test('checkpoint replay and tamper detection',async()=>{const {kernel,adapter}=setup();adapter.bind('adder',4);adapter.transition('adder','line',2);await adapter.execute('adder',{x:1,y:3});const cp=adapter.exportCheckpoint();const restored=ZhouyiExecutionAdapter.fromCheckpoint(kernel,cp);assert.equal(restored.state('adder').six,6);assert.deepEqual(restored.history(),adapter.history());cp.journal[1].to=8;assert.throws(()=>ZhouyiExecutionAdapter.fromCheckpoint(kernel,cp),/mismatch/);});
test('bound context is copy safe',()=>{const {adapter}=setup();adapter.bind('adder',0);const x=adapter.state('adder');x.lines[0]=1;x.metadata.witness='changed';assert.equal(adapter.state('adder').six,0);assert.equal(adapter.state('adder').metadata.witness,'computational');});
